import{_ as t,l as i,o as e,c as l,v as o,p as s,x as n,d as p,i as c,S as P}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"NPC 典型问题","description":"","frontmatter":{"title":"NPC 典型问题","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/npc-canonical.md","filePath":"cs/npc-canonical.md","lastUpdated":1789023840000}'),d={name:"cs/npc-canonical.md"};function A(h,a,N,C,T,_){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="npc-典型问题" tabindex="-1">NPC 典型问题 <a class="header-anchor" href="#npc-典型问题" aria-label="Permalink to &quot;NPC 典型问题&quot;">​</a></h1><div class="epigraph"><p>NP 完全是 NP 里的最难一层：所有 NP 问题都多项式归约到它。SAT 是第一块，其余由归约接上。</p><footer>—— 据 Cook, 1971；Karp, 1972；Garey and Johnson, Computers and Intractability, 1979 整理</footer></div><p>上一课<a href="/cs/np-reduction">多项式归约</a>钉了 \\(\\le_p\\) 的方向。本课不重画箭头。缺口是：<strong>NP 完全</strong>的定义，以及主干上要认得的几块——SAT/3SAT、顶点覆盖/独立集/团、哈密顿路/回路、子集和/背包判定——证明细节只点一条链，不把 Garey/Johnson 抄成词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(B\\) 是 NPC： \\(B\\in NP\\)，且每个 \\(A\\in NP\\) 有 \\(A\\le_p B\\)。等价地：某个已是 NPC 的 \\(A\\) 满足 \\(A\\le_p B\\) 且 \\(B\\in NP\\)。Cook–Levin：SAT 是 NPC。此后只需归约，不必再对任意 NP 语言写验证器编码。</p><p>缺口是这份杠杆，不是再解释证书。算法课里的图问题：最短路在 P，哈密顿路 NPC——同是「路」，约束从权和变成过每个点恰好一次。</p><h3 id="不要每个都从图灵机再证一遍" tabindex="-1">不要每个都从图灵机再证一遍 <a class="header-anchor" href="#不要每个都从图灵机再证一遍" aria-label="Permalink to &quot;不要每个都从图灵机再证一遍&quot;">​</a></h3><p>有了 SAT，3SAT 限制每子句三文字仍 NPC（加垫文字）。图问题从 3SAT 构造顶点与边。子集和从 3SAT 或从精确覆盖来。本课认脸谱与「从哪化来」，不写完每个 gadget。</p><p><span class="marginnote">Garey/Johnson 的附录清单是标准索引。本课只取课程序列后头会对照的：覆盖、团、哈密顿、子集和。旅行商判定同样 NPC，点名即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证 \\(B\\) 为 NPC：先给多项式验证器，再给从 3SAT（或清单上已知题）到 \\(B\\) 的 \\(f\\)。若只要 NP-难，可省「在 NP 内」（优化版搜索常如此）。\\(P=NP\\) 当且仅当任一 NPC 在 P。</p>',11)),(e(),s(P,null,{default:n(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAT%5B%22SAT%22%5D%20--%3E%20T3%5B%223SAT%22%5D%0A%20%20T3%20--%3E%20VC%5B%22%E9%A1%B6%E7%82%B9%E8%A6%86%E7%9B%96%20%2F%20%E7%8B%AC%E7%AB%8B%E9%9B%86%20%2F%20%E5%9B%A2%22%5D%0A%20%20T3%20--%3E%20HAM%5B%22%E5%93%88%E5%AF%86%E9%A1%BF%E8%B7%AF%22%5D%0A%20%20T3%20--%3E%20SS%5B%22%E5%AD%90%E9%9B%86%E5%92%8C%20%2F%20%E8%83%8C%E5%8C%85%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p><a href="/cs/knapsack">背包</a>判定在伪多项式算法下仍可 NPC：NPC 相对的是二进制输入长度。两句话必须同时记住。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>认题是为了后课：编译与系统仍在 P 里做词法、语法、寄存器着色的启发式；着色判定一般图上 NPC，那是<a href="/cs/regalloc-color">寄存器分配</a>会碰到的墙，本课先把「完全」这词备好。不要把启发式说成多项式最优算法。</p><p>补：3SAT 仍在 NP。P 里的 2SAT 是另一算法（蕴含图），本课点名对照，不写。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Cook–Levin 的表格构造。不引入 PCP、近似硬度。不把密码学单向函数写进来。算法栏到此结束：下一课起，对象从「问题难不难」换成「源文本如何变成可跑的程序」——源文本还不是图。</p><p>后课默认：NPC = NP 中且所有 NP 归约到它；SAT 为根，其余靠 Karp 归约。编译器通行证接的缺口是源程序作为字符串。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NPC：在 NP 中，且所有 NP 问题 \\(\\le_p\\) 到它；SAT 第一。</li><li>认 3SAT、覆盖/团、哈密顿、子集和；细节 gadget 不逐题写完。</li><li>背包 DP 与 NPC 不矛盾：伪多项式对数值，完全性对位数。</li><li>出处：Cook, 1971；Karp, 1972；Garey and Johnson, 1979。</li></ul>',9))])}const m=t(d,[["render",A]]);export{E as __pageData,m as default};
